(function (root, factory) {
  if (typeof module === 'object' && typeof module.exports === 'object') {
    module.exports = factory();
  } else if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else {
    root.Snow = factory();
  }
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';
/** @typedef {'none' | 'rain' | 'snow' | 'sleet'} PrecipitationMode */

const WEATHERAPI_SNOW_CODES = new Set([
  1066, 1114, 1117, 1210, 1213, 1216, 1219, 1222, 1225, 1237, 1255, 1258,
]);

const WEATHERAPI_RAIN_CODES = new Set([
  1063, 1150, 1153, 1168, 1171, 1180, 1183, 1186, 1189, 1192, 1195, 1240, 1243,
  1246,
]);

const WEATHERAPI_SLEET_CODES = new Set([
  1069, 1072, 1198, 1201, 1204, 1207, 1249, 1252,
]);

/**
 * @param {number} code
 * @returns {{ snow: boolean, rain: boolean }}
 */
function flagsFromWeatherApiCode(code) {
  if (WEATHERAPI_SLEET_CODES.has(code)) {
    return { snow: true, rain: true };
  }
  return {
    snow: WEATHERAPI_SNOW_CODES.has(code),
    rain: WEATHERAPI_RAIN_CODES.has(code),
  };
}

/**
 * @param {{ snow: boolean, rain: boolean }} flags
 * @returns {PrecipitationMode}
 */
function classifyPrecipitation(flags) {
  const { snow, rain } = flags;
  if (snow && rain) {
    return 'sleet';
  }
  if (snow) {
    return 'snow';
  }
  if (rain) {
    return 'rain';
  }
  return 'none';
}

/**
 * @param {object} config
 * @param {string} config.provider
 * @param {string} config.apiKey
 * @param {string} [config.city]
 * @param {number} [config.lat]
 * @param {number} [config.lon]
 * @param {'now' | 'today'} [config.scope]
 * @returns {Promise<PrecipitationMode>}
 */
async function fetchPrecipitationMode(config) {
  const { provider, apiKey, city, lat, lon, scope = 'now' } = config;

  if (!apiKey) {
    throw new Error('weather.apiKey is required when weather.enabled is true');
  }

  if (provider === 'openweathermap') {
    return fetchOpenWeatherMap({ apiKey, city, lat, lon, scope });
  }

  if (provider === 'weatherapi') {
    return fetchWeatherApi({ apiKey, city, lat, lon, scope });
  }

  throw new Error(`Unknown weather provider: ${provider}`);
}

async function fetchWeatherApi({ apiKey, city, lat, lon, scope }) {
  const q = city ?? (lat != null && lon != null ? `${lat},${lon}` : null);
  if (!q) {
    throw new Error('weather.city or weather.lat/lon is required');
  }

  const url = new URL('https://api.weatherapi.com/v1/forecast.json');
  url.searchParams.set('key', apiKey);
  url.searchParams.set('q', q);
  url.searchParams.set('days', '1');
  url.searchParams.set('aqi', 'no');
  url.searchParams.set('alerts', 'no');

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`WeatherAPI error: ${response.status}`);
  }

  const data = await response.json();
  const current = data.current;
  let flags = flagsFromWeatherApiCode(current.condition.code);

  if (scope === 'today') {
    const hours = data.forecast?.forecastday?.[0]?.hour ?? [];
    for (const hour of hours) {
      const hourFlags = flagsFromWeatherApiCode(hour.condition.code);
      flags = {
        snow: flags.snow || hourFlags.snow,
        rain: flags.rain || hourFlags.rain,
      };
    }
  } else if (current.precip_mm > 0) {
    if (!flags.snow && !flags.rain) {
      flags.rain = true;
    }
  } else if (!flags.snow && !flags.rain) {
    return 'none';
  }

  return classifyPrecipitation(flags);
}

async function fetchOpenWeatherMap({ apiKey, city, lat, lon, scope }) {
  const url = new URL('https://api.openweathermap.org/data/2.5/weather');
  url.searchParams.set('appid', apiKey);
  url.searchParams.set('units', 'metric');
  if (city) {
    url.searchParams.set('q', city);
  } else if (lat != null && lon != null) {
    url.searchParams.set('lat', String(lat));
    url.searchParams.set('lon', String(lon));
  } else {
    throw new Error('weather.city or weather.lat/lon is required');
  }

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`OpenWeatherMap error: ${response.status}`);
  }

  const data = await response.json();
  let flags = flagsFromOpenWeather(data);

  if (scope === 'today') {
    const forecastUrl = new URL('https://api.openweathermap.org/data/2.5/forecast');
    forecastUrl.searchParams.set('appid', apiKey);
    forecastUrl.searchParams.set('units', 'metric');
    if (city) {
      forecastUrl.searchParams.set('q', city);
    } else {
      forecastUrl.searchParams.set('lat', String(lat));
      forecastUrl.searchParams.set('lon', String(lon));
    }

    const forecastResponse = await fetch(forecastUrl);
    if (forecastResponse.ok) {
      const forecastData = await forecastResponse.json();
      for (const item of forecastData.list ?? []) {
        const itemFlags = flagsFromOpenWeather(item);
        flags = {
          snow: flags.snow || itemFlags.snow,
          rain: flags.rain || itemFlags.rain,
        };
      }
    }
  }

  return classifyPrecipitation(flags);
}

function flagsFromOpenWeather(data) {
  const weatherList = data.weather ?? [];
  let snow = false;
  let rain = false;

  for (const item of weatherList) {
    const main = (item.main ?? '').toLowerCase();
    const id = item.id ?? 0;
    if (main === 'snow' || (id >= 600 && id < 622)) {
      snow = true;
    }
    if (
      main === 'rain' ||
      main === 'drizzle' ||
      main === 'thunderstorm' ||
      (id >= 200 && id < 600)
    ) {
      rain = true;
    }
  }

  if (data.snow && (data.snow['1h'] > 0 || data.snow['3h'] > 0)) {
    snow = true;
  }
  if (data.rain && (data.rain['1h'] > 0 || data.rain['3h'] > 0)) {
    rain = true;
  }

  return { snow, rain };
}

class Snow {
  #icon;
  #rainIcon;
  #snowPlowImage;

  #countSnowflake;
  #countRaindrop;
  #snowBallsLength;
  #snowBallIterations;

  #snowBallupNum;
  #snowBallIterationsInterval;
  #clearSnowBalls;
  #reset;

  #showSnowBalls;
  #showSnowBallsIsMobile;
  #showSnowflakes;

  #weatherConfig;
  /** @type {'none' | 'rain' | 'snow' | 'sleet' | null} */
  #forcedPrecipitationMode = null;
  /** @type {'none' | 'rain' | 'snow' | 'sleet'} */
  #precipitationMode = 'snow';
  #weatherRefreshTimer;
  #snowBallGrowthInterval;

  #$snowflakesBox;
  #$raindropsBox;
  #$snowBallBox;
  #$layer;
  #$snowBallWrap;
  #$snowBall;
  #$snowPlow;

  #windowInnerWidth = window.innerWidth;
  #initialized = false;

  /** @param {number} value @param {number} min @param {number} max */
  #clampCount(value, min, max) {
    const n = Number(value);
    if (Number.isNaN(n)) {
      return min;
    }
    if (n < min) {
      return min;
    }
    if (n > max) {
      return max;
    }
    return n;
  }

  /**
   * @param {object} [config]
   * @param {boolean} [config.showSnowflakes=true]
   * @param {number} [config.countSnowflake=100] — снежинки, 0–100
   * @param {number} [config.countRaindrop=120] — капли дождя, 0–200
   * @param {number} [config.countRaindrops] — синоним countRaindrop
   * @param {string} [config.rainIconColor='#7eb8e8']
   */
  constructor(config = {}) {
    const {
      iconColor = '#a6e7ff',
      iconSize = 15,
      icon = `<svg fill="${iconColor}" xmlns="http://www.w3.org/2000/svg" width="${iconSize}px" height="${iconSize}px" viewBox="0 0 50 50"><path d="M24.97-.03A2 2 0 0 0 23 2v4.17l-1.9-1.89a2 2 0 0 0-1.43-.6 2 2 0 0 0-1.39 3.43L23 11.83v9.7l-8.4-4.85-1.74-6.46a2 2 0 0 0-1.9-1.51A2 2 0 0 0 9 11.25l.7 2.6-3.64-2.1a2 2 0 0 0-.95-.28 2 2 0 0 0-1.05 3.75l3.63 2.1-2.57.69a2 2 0 1 0 1.04 3.86l6.43-1.72L21.02 25l-8.41 4.85-6.4-1.72a2 2 0 0 0-.6-.07A2 2 0 0 0 5.18 32l2.53.67-3.64 2.1a2 2 0 1 0 2 3.47l3.63-2.1-.67 2.5a2 2 0 1 0 3.87 1.04l1.7-6.36L23 28.5v9.68l-4.68 4.68a2 2 0 1 0 2.83 2.83L23 43.83V48a2 2 0 1 0 4 0v-4.17l1.88 1.87a2 2 0 1 0 2.82-2.83l-4.7-4.7v-9.7l8.4 4.85 1.74 6.46A2 2 0 1 0 41 38.75l-.7-2.6 3.64 2.1a2 2 0 1 0 2-3.47l-3.64-2.1 2.56-.68a2 2 0 0 0-.5-3.94 2 2 0 0 0-.54.07l-6.41 1.72-8.38-4.83 8.43-4.86 6.38 1.7a2 2 0 1 0 1.03-3.85l-2.5-.68 3.57-2.05a2 2 0 0 0-.91-3.75 2 2 0 0 0-1.1.28l-3.64 2.1.7-2.6a2 2 0 0 0-2.03-2.54 2 2 0 0 0-1.84 1.51l-1.73 6.46L27 21.57v-9.74l4.72-4.72a2 2 0 1 0-2.83-2.83L27 6.18V2a2 2 0 0 0-2.03-2.03z"/></svg>`,
      snowPlowImage = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="63.793"><path fill="none" d="M100 0H78.448v21.552H100V0Z"/><path fill="#A8D6DA" fill-rule="evenodd" d="M48.276 32.759v1.724h13.793v-12.07H50L48.276 32.76Z"/><path fill="#C0F5F9" fill-rule="evenodd" d="M50 32.759h12.069v-8.621H51.724L50 32.758Z"/><path fill="#EBEBEB" d="M68.966 22.414v1.724h27.586v-1.724l-5.81-6.03a10.776 10.776 0 0 0-15.243-.276l-6.533 6.306Z"/><path fill="#C38325" fill-rule="evenodd" d="M70.69 37.931v1.724h24.138v-1.724l3.448-6.896v-8.621H67.24v8.62l3.449 6.897Z"/><path fill="#DA922A" fill-rule="evenodd" d="M48.276 32.759 32.759 37.93h-1.724v13.793H50V32.76h-1.724ZM100 37.931H60.345v18.966H100V37.93Z"/><path fill="#EA9D2D" fill-rule="evenodd" d="M98.276 22.414H67.24v8.62h31.035v-8.62ZM62.069 32.759H48.276v24.138h13.793V32.759Z"/><path fill="#F7F7F7" d="M0 62.431v1.362h25.862V53.448a6.897 6.897 0 0 0-12.911-3.373 5.174 5.174 0 0 0-5.994 5.895l-1.472.196A6.32 6.32 0 0 0 0 62.43Z"/><path fill="#EBEBEB" d="M.356 63.793h25.506v-6.896a6.897 6.897 0 0 0-12.911-3.374 5.174 5.174 0 0 0-5.994 5.895l-1.472.196a6.313 6.313 0 0 0-5.13 4.18Z"/><path fill="#DBDBDB" fill-rule="evenodd" d="M48.276 44.828H32.759v6.896h15.517v-6.896Z"/><path fill="#DA922A" fill-rule="evenodd" d="m79.31 37.931-1.724-6.896h10.345l-1.724 6.896H79.31Z"/><path fill="#EBEBEB" fill-rule="evenodd" d="M63.793 10.345a3.448 3.448 0 1 0-6.896 0 3.448 3.448 0 0 0 6.896 0ZM37.931 22.414a3.448 3.448 0 1 0-6.896 0 3.448 3.448 0 0 0 6.896 0ZM29.31 3.448a3.448 3.448 0 1 0-6.896 0 3.448 3.448 0 0 0 6.896 0ZM94.828 3.448a3.448 3.448 0 1 0-6.897 0 3.448 3.448 0 0 0 6.897 0ZM15.517 31.035a3.448 3.448 0 1 0-6.896 0 3.448 3.448 0 0 0 6.896 0ZM10.345 13.793a3.448 3.448 0 1 0-6.897 0 3.448 3.448 0 0 0 6.897 0Z"/><path fill="#EA9D2D" d="M21.983 56.897h3.88V34.483h3.307a3.589 3.589 0 0 1 3.589 3.588v23.136a2.586 2.586 0 0 1-2.587 2.586H18.965v-3.88a3.017 3.017 0 0 1 3.018-3.016Z"/><path fill="#C3C3C3" fill-rule="evenodd" d="M100 55.172a8.62 8.62 0 1 0-17.241 0 8.62 8.62 0 0 0 17.241 0Z"/><path fill="#EBEBEB" fill-rule="evenodd" d="M94.828 55.172a3.448 3.448 0 1 0-6.897 0 3.448 3.448 0 0 0 6.897 0Z"/><path fill="#C3C3C3" fill-rule="evenodd" d="M82.759 55.172a8.62 8.62 0 1 0-17.242 0 8.62 8.62 0 0 0 17.242 0Z"/><path fill="#EBEBEB" fill-rule="evenodd" d="M77.586 55.172a3.448 3.448 0 1 0-6.896 0 3.448 3.448 0 0 0 6.896 0Z"/><path fill="#C38325" fill-rule="evenodd" d="M65.517 50H55.172v6.897h10.345V50Z"/><path fill="#C3C3C3" fill-rule="evenodd" d="M55.172 55.172a8.62 8.62 0 1 0-17.241 0 8.62 8.62 0 0 0 17.241 0Z"/><path fill="#EBEBEB" fill-rule="evenodd" d="M50 55.172a3.448 3.448 0 1 0-6.896 0 3.448 3.448 0 0 0 6.896 0Z"/></svg>`,
      showSnowBalls = true,
      showSnowBallsIsMobile = true,
      showSnowflakes = true,
      countSnowflake = 100,
      countRaindrop = 120,
      countRaindrops,
      rainIconColor = '#7eb8e8',
      snowBallsLength = 10,
      snowBallIterations = 40,
      snowBallupNum = 1,
      snowBallIterationsInterval = 1000,
      clearSnowBalls = 20000,
      reset = -6,
      weather = null,
      precipitationMode: configPrecipitationMode,
    } = config;

    this.#forcedPrecipitationMode = this.#normalizePrecipitationMode(
      configPrecipitationMode ?? weather?.forceMode,
    );

    this.#icon = icon;
    this.#rainIcon = rainIconColor;
    this.#snowPlowImage = snowPlowImage;
    this.#showSnowBalls = showSnowBalls;
    this.#showSnowBallsIsMobile = showSnowBallsIsMobile;
    this.#showSnowflakes = showSnowflakes;
    this.#countSnowflake = this.#clampCount(countSnowflake, 0, 100);
    this.#countRaindrop = this.#clampCount(countRaindrops ?? countRaindrop, 0, 200);
    this.#snowBallsLength = snowBallsLength > 10 ? 10 : snowBallsLength;
    this.#snowBallIterations = snowBallIterations;
    this.#snowBallupNum = snowBallupNum > 3 ? 3 : snowBallupNum;
    this.#snowBallIterationsInterval = snowBallIterationsInterval;
    this.#clearSnowBalls = clearSnowBalls;
    this.#reset = reset;
    this.#weatherConfig = weather;

    if (this.#snowBallIterations < 10 && this.#snowBallupNum < 4) {
      this.#snowBallIterations = 10;
    } else if (this.#snowBallIterations > 40 && this.#snowBallupNum > 2) {
      this.#snowBallIterations = 40;
    }

    this.#boundResize = this.#resize.bind(this);
    window.addEventListener('resize', this.#boundResize);

    if (weather?.enabled) {
      this.#bootstrapWithWeather();
    } else if (this.#forcedPrecipitationMode) {
      this.#precipitationMode = this.#forcedPrecipitationMode;
      this.#init();
    } else {
      this.#precipitationMode = 'snow';
      this.#init();
    }
  }

  /** @param {unknown} mode */
  #normalizePrecipitationMode(mode) {
    if (mode === 'rain' || mode === 'snow' || mode === 'sleet' || mode === 'none') {
      return mode;
    }
    return null;
  }

  /** Количество капель (0–200) после clamp. */
  get countRaindrop() {
    return this.#countRaindrop;
  }

  /** Обновить число капель и перерисовать дождь, если он сейчас на экране. */
  setCountRaindrop(value) {
    this.#countRaindrop = this.#clampCount(value, 0, 200);
    if (!this.#initialized || !this.#includesRain()) {
      return;
    }
    if (!this.#$raindropsBox?.parentNode) {
      document.body.appendChild(this.#$raindropsBox);
    }
    this.#$raindropsBox.innerHTML = '';
    this.#createRaindrops();
  }

  #boundResize;

  /** Текущий режим осадков (после загрузки погоды или snow без weather). */
  get precipitationMode() {
    return this.#precipitationMode;
  }

  async #bootstrapWithWeather() {
    try {
      await this.#refreshWeatherMode();
    } catch (error) {
      console.warn('[Snow] Weather fetch failed:', error);
      this.#precipitationMode = 'none';
      if (!this.#initialized) {
        this.#init();
      } else {
        this.#applyPrecipitationEffects();
      }
    }

    const intervalMs = this.#weatherConfig.refreshInterval ?? 600000;
    this.#weatherRefreshTimer = window.setInterval(() => {
      this.#refreshWeatherMode().catch((error) => {
        console.warn('[Snow] Weather refresh failed:', error);
      });
    }, intervalMs);
  }

  async #refreshWeatherMode() {
    let mode;
    if (this.#forcedPrecipitationMode) {
      mode = this.#forcedPrecipitationMode;
    } else {
      mode = await fetchPrecipitationMode(this.#weatherConfig);
    }
    if (mode === this.#precipitationMode && this.#initialized) {
      return;
    }
    this.#precipitationMode = mode;
    if (!this.#initialized) {
      this.#init();
    } else {
      this.#applyPrecipitationEffects();
    }
  }

  #includesSnow() {
    return this.#precipitationMode === 'snow' || this.#precipitationMode === 'sleet';
  }

  #includesRain() {
    return this.#precipitationMode === 'rain' || this.#precipitationMode === 'sleet';
  }

  #init() {
    this.#$snowflakesBox = document.createElement('div');
    this.#$raindropsBox = document.createElement('div');
    this.#$snowBallBox = document.createElement('div');
    this.#$layer = document.createElement('div');
    this.#$snowBallWrap = document.createElement('div');
    this.#$snowPlow = document.createElement('div');

    this.#$snowflakesBox.className = 'snowflakes-box';
    this.#$raindropsBox.className = 'raindrops-box';
    this.#$snowBallBox.className = 'snowball-box';
    this.#$layer.className = 'snow-layer';
    this.#$snowBallWrap.className = 'snowball-wrap';
    this.#$snowPlow.className = 'snow-plow-img';
    this.#$snowPlow.innerHTML = this.#snowPlowImage;

    this.#initialized = true;
    this.#applyPrecipitationEffects();
  }

  #applyPrecipitationEffects() {
    this.#stopSnowBallGrowth();

    if (this.#$snowflakesBox?.parentNode) {
      this.#$snowflakesBox.remove();
    }
    if (this.#$raindropsBox?.parentNode) {
      this.#$raindropsBox.remove();
    }
    if (this.#$snowBallBox?.parentNode) {
      this.#$snowBallBox.remove();
    }

    this.#$snowflakesBox.innerHTML = '';
    this.#$raindropsBox.innerHTML = '';
    this.#$snowBallBox.innerHTML = '';
    this.#$layer = document.createElement('div');
    this.#$layer.className = 'snow-layer';
    this.#$snowBallWrap = document.createElement('div');
    this.#$snowBallWrap.className = 'snowball-wrap';
    this.#$snowBallWrap.innerHTML = '';
    this.#$snowBall = this.#$snowBallWrap.getElementsByTagName('a');

    if (this.#precipitationMode === 'none') {
      return;
    }

    if (this.#showSnowflakes && this.#includesSnow()) {
      document.body.appendChild(this.#$snowflakesBox);
      this.#createSnowflakes();
    }

    if (this.#includesRain()) {
      document.body.appendChild(this.#$raindropsBox);
      this.#createRaindrops();
    }

    if (this.#includesSnow() && this.#showSnowBalls) {
      this.#checkWindowWidth();
      if (this.#$snowBall.length) {
        for (const item of this.#$snowBall) {
          const w = item.clientWidth;
          item.style.height = w + 'px';
        }
      }
      this.#activateSnowBallsChangeTranslate();
    }
  }

  #resize() {
    this.#windowInnerWidth = window.innerWidth;
    if (!this.#initialized || this.#precipitationMode === 'none') {
      return;
    }

    if (this.#includesSnow() && this.#showSnowflakes) {
      this.#$snowflakesBox.innerHTML = '';
      this.#createSnowflakes();
    }

    if (this.#includesRain()) {
      this.#$raindropsBox.innerHTML = '';
      this.#createRaindrops();
    }

    if (this.#includesSnow() && this.#showSnowBalls) {
      this.#stopSnowBallGrowth();
      this.#$snowBallBox.innerHTML = '';
      this.#$layer = document.createElement('div');
      this.#$layer.className = 'snow-layer';
      this.#$snowBallWrap = document.createElement('div');
      this.#$snowBallWrap.className = 'snowball-wrap';
      this.#checkWindowWidth();
    }
  }

  destroy() {
    window.removeEventListener('resize', this.#boundResize);
    if (this.#weatherRefreshTimer) {
      clearInterval(this.#weatherRefreshTimer);
    }
    this.#stopSnowBallGrowth();
    this.#$snowflakesBox?.remove();
    this.#$raindropsBox?.remove();
    this.#$snowBallBox?.remove();
    this.#initialized = false;
  }

  #stopSnowBallGrowth() {
    if (this.#snowBallGrowthInterval) {
      clearInterval(this.#snowBallGrowthInterval);
      this.#snowBallGrowthInterval = null;
    }
  }

  #activateSnowBallsChangeTranslate() {
    if (!this.#includesSnow() || !this.#showSnowBalls) {
      return;
    }

    let iterations = 0;

    const snowBallsChangeTranslate = () => {
      iterations++;
      if (iterations >= this.#snowBallIterations) {
        this.#stopSnowBallGrowth();
        this.#$layer.classList.add('up-max');

        setTimeout(() => {
          this.#activateAnimate();
        }, this.#clearSnowBalls);
      }

      for (const $snowBallEl of this.#$snowBall) {
        const style = window.getComputedStyle($snowBallEl);
        const matrix = new DOMMatrix(style.transform);
        const transformMatrixY = matrix.m42;
        const snowBallupNumM = -this.#snowBallupNum;
        const up = transformMatrixY + snowBallupNumM;

        $snowBallEl.style.transform = 'translateY(' + up + 'px )';
      }
    };

    this.#snowBallGrowthInterval = setInterval(
      snowBallsChangeTranslate,
      this.#snowBallIterationsInterval,
    );
  }

  #activateAnimate() {
    if (!this.#$layer.classList.contains('up-max')) {
      return;
    }

    for (const $snowBallEl of this.#$snowBall) {
      if (!$snowBallEl.classList.contains('active')) {
        $snowBallEl.classList.add('active');
      }

      if (!this.#$snowPlow.classList.contains('active')) {
        this.#$snowPlow.classList.add('active');
      }

      $snowBallEl.onanimationend = () => {
        $snowBallEl.style.transform = 'translateY(' + this.#reset + 'px )';
        this.#$snowPlow.classList.remove('active');
        setTimeout(() => {
          if ($snowBallEl.classList.contains('active')) {
            $snowBallEl.classList.remove('active');
          }

          this.#$layer.classList.remove('up-max');

          this.#activateSnowBallsChangeTranslate();
        }, 1000);
      };

      this.#$snowPlow.onanimationend = () => {
        this.#$snowPlow.classList.remove('active');
      };
    }
  }

  #createSnowflakes() {
    const count =
      this.#precipitationMode === 'sleet'
        ? Math.ceil(this.#countSnowflake * 0.6)
        : this.#countSnowflake;

    for (let i = 0; i < count; i++) {
      const snowflake = document.createElement('span');

      snowflake.className = 'snowflake';
      snowflake.innerHTML = this.#icon;
      this.#$snowflakesBox.appendChild(snowflake);
    }
  }

  #createRaindrops() {
    const count = this.#getRaindropRenderCount();

    for (let i = 0; i < count; i++) {
      const drop = document.createElement('span');
      const left = Math.random() * 100;
      const duration = 0.45 + Math.random() * 0.85;
      const delay = Math.random() * duration;
      const height = 10 + Math.random() * 16;
      const opacity = 0.35 + Math.random() * 0.45;

      drop.className = 'raindrop';
      drop.style.left = `${left}vw`;
      drop.style.animationDuration = `${duration}s`;
      drop.style.animationDelay = `-${delay}s`;
      drop.style.height = `${height}px`;
      drop.style.opacity = String(opacity);
      drop.style.background = `linear-gradient(transparent, ${this.#rainIcon})`;

      this.#$raindropsBox.appendChild(drop);
    }
  }

  #createSnowBallsBox() {
    this.#$layer.appendChild(this.#$snowBallWrap);
    this.#$snowBallBox.appendChild(this.#$layer);
    document.body.appendChild(this.#$snowBallBox);
    this.#$snowBall = this.#$snowBallWrap.getElementsByTagName('a');
  }

  #createSnowBalls() {
    if (this.#$snowBallWrap.children.length !== 0) {
      return;
    }

    for (let i = 0; i < this.#snowBallsLength; i++) {
      const $snowBall = document.createElement('a');
      $snowBall.innerHTML = `${this.#icon}${this.#icon}`;
      this.#$snowBallWrap.appendChild($snowBall);
    }

    this.#$snowBallWrap.appendChild(this.#$snowPlow);
    this.#$snowBall = this.#$snowBallWrap.getElementsByTagName('a');
  }

  #checkWindowWidth() {
    if (!this.#showSnowBalls || !this.#includesSnow()) {
      return;
    }

    if (!this.#showSnowBallsIsMobile) {
      if (this.#windowInnerWidth > 1024) {
        this.#createSnowBallsBox();
        this.#createSnowBalls();
      }
      return;
    }

    if (this.#windowInnerWidth < 1024) {
      if (this.#snowBallIterations > 20) {
        this.#snowBallIterations = 20;
      }

      if (this.#snowBallsLength > 3) {
        this.#snowBallsLength = 3;
      }

      if (this.#snowBallupNum > 2) {
        this.#snowBallupNum = 2;
      }
    }

    this.#createSnowBallsBox();
    this.#createSnowBalls();
  }

  #getRaindropRenderCount() {
    if (this.#precipitationMode === 'sleet') {
      return Math.ceil(this.#countRaindrop * 0.85);
    }
    return this.#countRaindrop;
  }
}

  return Snow;
});
